<#
.SYNOPSIS
    ETS2 Convoi Launcher - Classic White Edition
    Copyright © 2026 MrWolfTv
#>

Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase, System.Windows.Forms

# --- TON CODE BASE64 ICI ---
$Base64Image = ""
# --- Configuration des chemins ---
$ConfigDir = "$env:APPDATA\ets2Launcher"
if (-not (Test-Path $ConfigDir)) { New-Item -ItemType Directory -Path $ConfigDir | Out-Null }
$ConfigFile = Join-Path $ConfigDir "launcher_config.json"

$config = [PSCustomObject]@{ 
    TruckersMP = "C:\Program Files\TruckersMP Launcher\TruckersMP-Launcher.exe" 
    TrucksBook = "C:\Program Files (x86)\TrucksBook Client\TB Client.exe"
    Trucky     = "$env:LOCALAPPDATA\Trucky\Trucky.exe"
    PickUp     = "" 
}

if (Test-Path $ConfigFile) {
    try { 
        $temp = Get-Content $ConfigFile -Raw | ConvertFrom-Json 
        foreach ($p in $temp.psobject.Properties) { if ($p.Value) { $config.$($p.Name) = $p.Value } }
    } catch { }
}

# --- XAML ---
$XAML = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="ETS2 Launcher - By MrWolfTv" Height="600" Width="800"
        WindowStartupLocation="CenterScreen" ResizeMode="CanMinimize" Topmost="False" Background="Black">
    
    <Window.Resources>
        <Style x:Key="CustomButtonStyle" TargetType="Button">
            <Setter Property="Foreground" Value="White"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <!-- Bordure blanche fixée -->
            <Setter Property="BorderBrush" Value="White"/>
            <Setter Property="BorderThickness" Value="1.5"/>
            <Setter Property="Height" Value="50"/>
            <Setter Property="Width" Value="320"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="border" 
                                Background="{TemplateBinding Background}" 
                                BorderBrush="{TemplateBinding BorderBrush}" 
                                BorderThickness="{TemplateBinding BorderThickness}" 
                                CornerRadius="15">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="border" Property="Opacity" Value="0.8"/>
                                <Setter Property="Cursor" Value="Hand"/>
                                <!-- La bordure reste blanche au survol -->
                                <Setter Property="BorderBrush" Value="White"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
    </Window.Resources>

    <Grid>
        <Image x:Name="BackgroundImage" Stretch="UniformToFill" HorizontalAlignment="Center" VerticalAlignment="Center"/>
        <Rectangle Fill="#77000000"/>
        
        <TextBlock Text="Copyright MrWolfTv" Foreground="#33FFFFFF" VerticalAlignment="Top" HorizontalAlignment="Right" Margin="10" FontSize="10"/>

        <StackPanel x:Name="MainMenu" VerticalAlignment="Center" HorizontalAlignment="Center">
            <Button x:Name="LaunchButton" Content="Lancer les applications" Background="#4682B4" Margin="0,8" Style="{StaticResource CustomButtonStyle}"/>
            <Button x:Name="CloseButton" Content="Tout arreter" Background="#DC143C" Margin="0,8" Style="{StaticResource CustomButtonStyle}"/>
            <Button x:Name="OpenSettings" Content="Parametres" Background="#2E8B57" Margin="0,8" Style="{StaticResource CustomButtonStyle}"/>
            <Button x:Name="QuitButton" Content="Quitter" Background="#333333" Margin="0,8" Style="{StaticResource CustomButtonStyle}"/>
        </StackPanel>

        <Grid x:Name="SettingsMenu" Visibility="Collapsed" Background="#F21A1A1A">
            <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center" Width="650">
                <TextBlock Text="Configuration des chemins" Foreground="White" FontSize="18" FontWeight="Bold" Margin="0,0,0,20" TextAlignment="Center"/>
                <TextBlock Text="TruckersMP" Foreground="White" FontSize="11"/><DockPanel Margin="0,2,0,10"><Button x:Name="BtnTMP" Content="..." DockPanel.Dock="Right" Width="40" Height="25"/><TextBox x:Name="PathTMP" IsReadOnly="True" Background="#333" Foreground="White" Height="25" VerticalContentAlignment="Center"/></DockPanel>
                <TextBlock Text="TrucksBook" Foreground="White" FontSize="11"/><DockPanel Margin="0,2,0,10"><Button x:Name="BtnTB" Content="..." DockPanel.Dock="Right" Width="40" Height="25"/><TextBox x:Name="PathTB" IsReadOnly="True" Background="#333" Foreground="White" Height="25" VerticalContentAlignment="Center"/></DockPanel>
                <TextBlock Text="Trucky" Foreground="White" FontSize="11"/><DockPanel Margin="0,2,0,10"><Button x:Name="BtnTrucky" Content="..." DockPanel.Dock="Right" Width="40" Height="25"/><TextBox x:Name="PathTrucky" IsReadOnly="True" Background="#333" Foreground="White" Height="25" VerticalContentAlignment="Center"/></DockPanel>
                <TextBlock Text="PickUp" Foreground="White" FontSize="11"/><DockPanel Margin="0,2,0,10"><Button x:Name="BtnPickUp" Content="..." DockPanel.Dock="Right" Width="40" Height="25"/><TextBox x:Name="PathPickUp" IsReadOnly="True" Background="#333" Foreground="White" Height="25" VerticalContentAlignment="Center"/></DockPanel>
                <Button x:Name="SaveSettings" Content="Sauvegarder" Background="#2E8B57" Height="45" Width="200" Margin="0,15,0,0" Style="{StaticResource CustomButtonStyle}"/>
            </StackPanel>
        </Grid>

        <TextBlock x:Name="StatusLabel" Text="Pret a rouler" VerticalAlignment="Bottom" HorizontalAlignment="Center" Margin="0,0,0,40" Foreground="White" FontSize="14"/>
    </Grid>
</Window>
"@

$window = [Windows.Markup.XamlReader]::Load([System.Xml.XmlReader]::Create([System.IO.StringReader]$XAML))

# --- IMAGE BASE64 ---
if ($Base64Image -and $Base64Image.Length -gt 100) {
    try {
        $imageBytes = [Convert]::FromBase64String($Base64Image)
        $ms = New-Object System.IO.MemoryStream($imageBytes, 0, $imageBytes.Length)
        $bitmap = New-Object System.Windows.Media.Imaging.BitmapImage
        $bitmap.BeginInit(); $bitmap.StreamSource = $ms; $bitmap.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad; $bitmap.EndInit()
        $window.FindName("BackgroundImage").Source = $bitmap
    } catch { }
}

# --- Logique ---
$MainMenu = $window.FindName("MainMenu"); $SettingsMenu = $window.FindName("SettingsMenu")
$StatusLabel = $window.FindName("StatusLabel")
$PathTMP = $window.FindName("PathTMP"); $PathTB = $window.FindName("PathTB")
$PathTrucky = $window.FindName("PathTrucky"); $PathPickUp = $window.FindName("PathPickUp")

$PathTMP.Text = $config.TruckersMP; $PathTB.Text = $config.TrucksBook
$PathTrucky.Text = $config.Trucky; $PathPickUp.Text = $config.PickUp

function Get-File {
    $d = New-Object System.Windows.Forms.OpenFileDialog
    $d.Filter = "Exe (*.exe)|*.exe"
    if($d.ShowDialog() -eq "OK") { return $d.FileName }
}

$window.FindName("OpenSettings").Add_Click({ $SettingsMenu.Visibility = "Visible"; $MainMenu.Visibility = "Collapsed" })
$window.FindName("QuitButton").Add_Click({ $window.Close() })
$window.FindName("BtnTMP").Add_Click({ $PathTMP.Text = Get-File })
$window.FindName("BtnTB").Add_Click({ $PathTB.Text = Get-File })
$window.FindName("BtnTrucky").Add_Click({ $PathTrucky.Text = Get-File })
$window.FindName("BtnPickUp").Add_Click({ $PathPickUp.Text = Get-File })

$window.FindName("SaveSettings").Add_Click({ 
    $config.TruckersMP = $PathTMP.Text; $config.TrucksBook = $PathTB.Text
    $config.Trucky = $PathTrucky.Text; $config.PickUp = $PathPickUp.Text
    $config | ConvertTo-Json | Set-Content $ConfigFile
    $SettingsMenu.Visibility = "Collapsed"; $MainMenu.Visibility = "Visible"
    $StatusLabel.Text = "Configuration sauvegardee !"
})

$window.FindName("LaunchButton").Add_Click({
    $StatusLabel.Text = "Lancement en cours..."
    $procs = @("eurotrucks2", "TruckersMP-Launcher", "TB Client", "Trucky", "pickupvtm-tracker")
    foreach($pr in $procs) { Stop-Process -Name $pr -Force -ErrorAction SilentlyContinue }
    Start-Sleep -Milliseconds 500
    $apps = @($PathTMP.Text, $PathTB.Text, $PathTrucky.Text, $PathPickUp.Text)
    foreach($app in $apps) { if (![string]::IsNullOrWhiteSpace($app) -and (Test-Path $app)) { Start-Process $app } }
    $StatusLabel.Text = "Bonne route chauffeur !"
})

$window.FindName("CloseButton").Add_Click({
    $procs = @("eurotrucks2", "TruckersMP-Launcher", "TB Client", "Trucky", "pickupvtm-tracker")
    foreach($pr in $procs) { Stop-Process -Name $pr -Force -ErrorAction SilentlyContinue }
    $StatusLabel.Text = "Tout a ete arrete."
})

$window.ShowDialog() | Out-Null